// Shared content configuration: replace with an HR-managed API response later.
const homeConfig = { welcome: '👋 Sienna，本月 6 门课程上新', banner: { eyebrow: 'NOVEMBER · 2026', title: '11 月学习上新', action: '探索新课程' } };
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',book:'<path d="M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z"/>',exam:'<rect x="5" y="4" width="14" height="17" rx="3"/><path d="M9 3h6v4H9zM9 12h6M9 16h4"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 5v6h6M12 7v6l4 2"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m8 14-2 8 6-3 6 3-2-8"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4M12 2v2"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',chart:'<path d="M5 19v-6M12 19V5M19 19V9"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',message:'<path d="M4 4h16v13H9l-5 4Z M8 9h8M8 13h5"/>',logo:'<path d="M4 5h16M12 5v15M5 11v5a4 4 0 0 0 4 4h6a4 4 0 0 0 4-4v-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const initialCourses=[{id:'culture',title:'企业文化与价值观',progress:80,tag:'新员工必修 · 企业文化',art:'culture',duration:45},{id:'security',title:'信息安全培训',progress:60,tag:'全员必修 · 安全合规',art:'security',duration:30},{id:'product',title:'产品基础介绍',progress:40,tag:'岗位通识 · 产品知识',art:'product',duration:50},{id:'ai',title:'AI 工具应用实战',progress:0,tag:'能力提升 · 新课',art:'product',duration:40},{id:'data',title:'数据分析入门',progress:0,tag:'能力提升 · 新课',art:'security',duration:60}];
const finishedTitles=['高效沟通与协作','职场时间管理','团队协作基础','客户服务意识','公司制度与规范','办公工具入门','职业发展规划','项目管理基础','商务礼仪','目标管理','问题分析与解决','工作汇报技巧'];
let saved={};try{saved=JSON.parse(localStorage.getItem('learning-progress-v1')||'{}')}catch{}
const courses=[...initialCourses,...finishedTitles.map((title,i)=>({id:'done'+i,title,progress:100,tag:'通用能力 · 已完成',art:['culture','security','product'][i%3],duration:30}))].map(c=>({...c,progress:saved[c.id]??c.progress}));
const state={page:'home',tab:'active',query:'',month:10,year:2026,picked:1,examStarted:false,examResult:null,role:null};
const navs=[['home','首页','home'],['learning','我的学习','book'],['exams','我的考试','exam'],['records','学习记录','history'],['certificates','我的证书','award']];
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function art(type){return `<div class="art ${type}" aria-hidden="true">${type==='security'?'<div class="lock"></div>':type==='product'?'<div class="blocks"></div>':'<div class="ring"></div><div class="orb"></div>'}</div>`}
function courseCard(c){return `<article class="course" data-course="${c.id}" tabindex="0" role="button" aria-label="查看${c.title}">${art(c.art)}<span class="tag">${c.tag}</span><h3>${c.title}</h3><div class="progress-caption"><span>学习进度</span><b>${c.progress}%</b></div><div class="track" role="progressbar" aria-valuenow="${c.progress}" aria-valuemin="0" aria-valuemax="100" aria-label="${c.title}学习进度"><span style="width:${c.progress}%"></span></div><button class="continue" data-course="${c.id}">${c.progress===100?'回顾课程':c.progress?'继续学习':'开始学习'}${icon('arrow')}</button></article>`}
function courseList(){let list=courses.filter(c=>state.tab==='active'?c.progress>0&&c.progress<100:state.tab==='pending'?c.progress===0:c.progress===100);if(state.query.trim())list=list.filter(c=>c.title.toLowerCase().includes(state.query.trim().toLowerCase()));return list.map(courseCard).join('')||'<div class="empty">没有找到相关课程</div>'}
function tabs(){return `<div class="tabs" role="tablist" aria-label="课程状态">${[['active','进行中',courses.filter(c=>c.progress>0&&c.progress<100).length],['pending','未开始',courses.filter(c=>c.progress===0).length],['done','已完成',courses.filter(c=>c.progress===100).length]].map(([id,label,count])=>`<button role="tab" aria-selected="${state.tab===id}" class="${state.tab===id?'selected':''}" data-tab="${id}">${label} (${count})</button>`).join('')}</div>`}
function learningSection(){return `<section class="learning"><div class="section-heading"><h2>我的学习</h2><button class="textbutton" data-nav="learning">全部课程 ${icon('arrow')}</button></div>${tabs()}<div class="course-grid" id="course-list">${courseList()}</div></section>`}
function calendar(){const first=(new Date(state.year,state.month,1).getDay()+6)%7;const count=new Date(state.year,state.month+1,0).getDate();const prevCount=new Date(state.year,state.month,0).getDate();const cells=Array.from({length:Math.ceil((first+count)/7)*7},(_,i)=>{const day=i-first+1,valid=day>0&&day<=count;return `<button ${valid?`data-day="${day}"`:'disabled'} class="${!valid?'outside':''} ${valid&&day===1&&state.month===10&&state.year===2026?'today':''} ${valid&&[15,16].includes(day)&&state.month===10&&state.year===2026?'deadline':''} ${valid&&state.picked===day?'picked':''}" aria-label="${valid?`${state.month+1}月${day}日`:`相邻月份 ${day<1?prevCount+day:day-count}日`}">${day<1?prevCount+day:day>count?day-count:day}</button>`}).join('');return `<div class="calendar"><h2>我的学习日历</h2><div class="calendar-month"><strong>${state.year} 年 ${state.month+1} 月</strong><div><button data-month="-1" aria-label="上个月">‹</button><button data-month="1" aria-label="下个月">›</button></div></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(d=>`<span class="dayname">${d}</span>`).join('')}${cells}</div><div class="calendar-key"><span>今天</span><span>任务截止</span></div></div>`}
function tasks(){return `<section class="tasks"><h2>本周任务</h2><div class="task"><div class="task-top"><span class="task-icon">${icon('book')}</span><div><h3>信息安全培训</h3><p>截止 11 月 15 日</p></div></div><button data-course="security">继续学习 ${icon('arrow')}</button></div><div class="task"><div class="task-top"><span class="task-icon purple">${icon('exam')}</span><div><h3>新员工入职考试</h3><p>截止 11 月 16 日</p></div></div><button data-nav="exams">开始考试 ${icon('arrow')}</button></div></section>`}
function updates(){return `<section class="updates"><div class="section-heading"><h2>最近更新</h2></div><div class="update-list">${[['ai','AI 工具应用实战','今天上线','spark',true],['data','数据分析入门','昨天上线','chart',true],['done0','高效沟通与协作','10月30日上线','message',false]].map(([id,title,date,ic,isNew])=>`<button class="update" data-course="${id}"><span class="update-icon">${icon(ic)}</span><div><h3>${title}</h3><p>${isNew?'<span class="new">新课</span>':''}${date}</p></div></button>`).join('')}</div></section>`}
function home(){return `<div class="dashboard"><div class="left-column"><section class="banner"><p class="eyebrow">${homeConfig.banner.eyebrow}</p><h2>${homeConfig.banner.title}</h2><button class="primary" data-new>${homeConfig.banner.action}${icon('arrow')}</button><div class="banner-art" aria-hidden="true"><div class="ring"></div><div class="orb"></div><div class="pill"></div><span class="star">✦</span></div></section><div class="stats">${[['待学习','3','门','book','learning'],['学习进度','72','%','chart','records'],['待考试','1','场','exam','exams']].map(([label,value,unit,ic,target])=>`<button class="stat" data-nav="${target}"><span class="stat-label">${icon(ic)}${label}</span><strong>${value}<small>${unit}</small></strong><span class="stat-arrow">${icon('arrow')}</span></button>`).join('')}</div>${learningSection()}${updates()}</div><aside class="right-column"><div class="panel">${calendar()}${tasks()}</div></aside></div>`}
function exams(){if(state.examResult!==null)return `<div class="page-card"><span class="badge">体验已完成</span><h3 style="margin-top:20px">新员工入职考试</h3><p>示例题得分：${state.examResult} / 100</p><p>这是考试交互演示，未生成正式考试成绩。</p><button class="primary" data-exam-reset>返回考试列表</button></div>`;if(state.examStarted)return `<div class="page-card"><span class="badge">示例考试 · 1 / 1</span><h3 style="margin-top:25px">发现可疑邮件时，应该如何处理？</h3><form id="exam-form"><div class="exam-options"><label><input type="radio" name="answer" value="a" required>直接打开附件确认内容</label><label><input type="radio" name="answer" value="b">通过公司规定渠道报告可疑邮件</label><label><input type="radio" name="answer" value="c">转发给所有同事</label></div><button class="primary" type="submit">提交示例答案</button></form><p>原型演示题，正式题库待接入。</p></div>`;return `<div class="page-card"><span class="badge">待考试</span><h3 style="margin-top:20px">新员工入职考试</h3><p>截止 11 月 16 日</p><p>考试页原型，可体验一道示例题。</p><button class="primary" data-exam-start>开始体验 ${icon('arrow')}</button></div>`}
function records(){return `<div class="page-card"><div class="section-heading"><h2>学习足迹</h2><span class="badge">原型示例记录</span></div>${courses.filter(c=>c.progress>0).slice(0,8).map(c=>`<div class="record"><strong>${c.title}</strong><span>${c.progress===100?'已完成':'学习中'} · ${c.progress}%</span><button class="textbutton" data-course="${c.id}">查看课程 ${icon('arrow')}</button></div>`).join('')}</div>`}
function certificates(){return `<div class="page-card"><div class="certificate">${icon('award')}<h3>高效沟通与协作</h3><p>课程结业证书 · 示例</p><p>Sienna</p><button class="primary" data-certificate>预览证书</button></div></div>`}
function render(){if(window.renderPortal)return window.renderPortal();app.innerHTML=`<aside class="sidebar"><button class="logo" data-nav="home" aria-label="学习空间首页">${icon('logo')}</button><nav class="nav" aria-label="主导航">${navs.map(([id,title,ic])=>`<button data-nav="${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span>${title}</span></button>`).join('')}</nav><span class="sidebar-bottom">LEARNING SPACE</span></aside><main class="workspace"><header class="topbar"><h1>${state.page==='home'?homeConfig.welcome:navs.find(n=>n[0]===state.page)[1]}</h1><div class="search">${icon('search')}<input id="search" type="search" aria-label="搜索课程" placeholder="搜索课程、学习内容" value="${esc(state.query)}"></div><button class="iconbtn" data-notifications aria-label="消息">${icon('bell')}<span class="notification-dot"></span></button><button class="avatar" data-profile aria-label="个人资料">S</button></header><div id="page">${state.page==='home'?home():`<section class="subpage">${state.page==='learning'?learningSection():state.page==='exams'?exams():state.page==='records'?records():certificates()}</section>`}</div></main>`}
let previousFocus;function modal(content,drawer=false){previousFocus=document.activeElement;overlay.innerHTML=`<div class="scrim"><section class="${drawer?'drawer':'dialog'}" role="dialog" aria-modal="true" aria-label="详情"><button class="close" data-close aria-label="关闭">×</button>${content}</section></div>`;app.inert=true;overlay.querySelector('.close').focus();document.body.style.overflow='hidden'}
function close(){overlay.innerHTML='';app.inert=false;document.body.style.overflow='';previousFocus?.focus()}
function openCourse(id){const c=courses.find(x=>x.id===id);if(!c)return;modal(`${art(c.art)}<h2>${c.title}</h2><p>${c.tag} · ${c.duration} 分钟</p><div class="progress-caption"><span>当前学习进度</span><b>${c.progress}%</b></div><div class="track"><span style="width:${c.progress}%"></span></div><h3 style="margin-top:30px">课程目录</h3>${['课程导读','核心知识与应用','案例回顾与总结'].map((s,i)=>`<div class="chapter"><span>0${i+1}</span>${s}</div>`).join('')}<button class="primary" data-advance="${c.id}">${c.progress===100?'回顾课程内容':'体验学习 · 进度增加 10%'}${icon('arrow')}</button><p>当前为交互原型，课程媒体待接入。体验进度仅保存在本浏览器。</p>`,true)}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3000)}
function navigate(page){if(window.navigatePortal)return window.navigatePortal(page);state.page=page;state.query='';location.hash=page;render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-course]');if(e.target.classList.contains('scrim'))close();if(!target)return;if(target.hasAttribute('data-close'))return close();if(target.dataset.nav)return navigate(target.dataset.nav);if(target.hasAttribute('data-logout'))return window.logoutPortal?.();if(target.dataset.adminAction)return window.adminAction?.(target.dataset.adminAction,target.dataset.id);if(target.dataset.adminTab)return window.adminTab?.(target.dataset.adminTab);if(target.dataset.adminEdit)return window.adminEdit?.(target.dataset.adminEdit,target.dataset.id);if(target.hasAttribute('data-new')){state.tab='pending';navigate('learning');return}if(target.dataset.tab){state.tab=target.dataset.tab;render();return}if(target.dataset.course)return openCourse(target.dataset.course);if(target.hasAttribute('data-month')){state.month+=Number(target.dataset.month);if(state.month>11){state.month=0;state.year++}if(state.month<0){state.month=11;state.year--}state.picked=null;render();return}if(target.dataset.day){state.picked=Number(target.dataset.day);render();toast(state.year===2026&&state.month===10&&state.picked===15?'11 月 15 日：信息安全培训截止':state.year===2026&&state.month===10&&state.picked===16?'11 月 16 日：新员工入职考试截止':`${state.month+1} 月 ${state.picked} 日暂无到期任务`);return}if(target.dataset.advance){const c=courses.find(c=>c.id===target.dataset.advance);if(c.progress===100){toast('课程回顾已打开，正式内容待接入');return}c.progress=Math.min(100,c.progress+10);try{localStorage.setItem('learning-progress-v1',JSON.stringify(Object.fromEntries(courses.map(c=>[c.id,c.progress]))))}catch{}render();openCourse(c.id);toast(`体验进度已更新至 ${c.progress}%`);return}if(target.hasAttribute('data-exam-start')){state.examStarted=true;render();return}if(target.hasAttribute('data-exam-reset')){state.examStarted=false;state.examResult=null;render();return}if(target.hasAttribute('data-notifications'))return modal('<h2>消息</h2><div class="chapter">AI 工具应用实战已上线</div><div class="chapter">信息安全培训将于 11 月 15 日截止</div>');if(target.hasAttribute('data-profile'))return modal('<h2>Sienna</h2><p>员工学习空间</p><p>当前为员工端原型账号。</p>');if(target.hasAttribute('data-certificate'))return modal(`<div class="certificate">${icon('award')}<h3>课程结业证书</h3><p>高效沟通与协作</p><h2>Sienna</h2><p>示例证书 · 非正式凭证</p></div>`)});
document.addEventListener('input',e=>{if(e.target.id!=='search')return;state.query=e.target.value;if(state.page!=='learning'){state.page='learning';state.tab='active';render();const input=document.getElementById('search');input.focus();input.setSelectionRange(input.value.length,input.value.length)}const list=document.getElementById('course-list');if(state.query.trim()){list.innerHTML=courses.filter(c=>c.title.toLowerCase().includes(state.query.trim().toLowerCase())).map(courseCard).join('')||'<div class="empty">没有找到相关课程，请试试其他关键词</div>'}else list.innerHTML=courseList()});
document.addEventListener('submit',e=>{if(window.adminSubmit?.(e))return;if(e.target.id==='exam-form'){e.preventDefault();state.examResult=new FormData(e.target).get('answer')==='b'?100:0;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(overlay.children.length&&e.key==='Tab'){const focusables=[...overlay.querySelectorAll('button,input,[tabindex="0"]')];const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[data-course]')){e.preventDefault();openCourse(e.target.dataset.course)}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(navs.some(n=>n[0]===page)&&page!==state.page){state.page=page;state.query='';render()}});if(navs.some(n=>n[0]===location.hash.slice(1)))state.page=location.hash.slice(1);
